actions.script:
def result = ec.service.sync().name('zenith.pos.PosCreditServices.get#PosCreditHistory').parameter('transactionId',ec.web.parameters.transactionId).call()
def success = !ec.message.hasError(); def error = ec.message.errorsString; ec.message.clearErrors()
ec.web.sendJsonResponse([success:success,error:error,history:result?.history])
